// A base class whose method is reached ONLY as `this.ok(...)` from a subclass.
class BaseHandler {
  ok(res, body) {
    return res.status(200).json(body);
  }

  fail(res, status, message) {
    return res.status(status).json({ error: message });
  }
}

module.exports = { BaseHandler };

