const { BaseHandler } = require("./base");
const { OrderStore } = require("../stores/orderStore");

class OrdersHandler extends BaseHandler {
  constructor() {
    super();
    this.store = new OrderStore();
  }

  list(req, res) {
    return this.ok(res, this.store.list());
  }

  find(req, res) {
    const order = this.store.get(Number(req.params.id));
    if (!order) return this.fail(res, 404, "order not found");
    return this.ok(res, order);
  }
}

module.exports = { OrdersHandler };

