const { Router } = require("express");
const { requireAuth } = require("../auth");
const { OrderStore, searchByItemPrefix } = require("../stores/orderStore");

const router = Router();
const store = new OrderStore();

router.get("/", (req, res) => {
  res.json(store.list());
});

router.get("/search", (req, res) => {
  res.json(searchByItemPrefix(store.list(), req.query.q));
});

router.get("/:id", (req, res) => {
  const order = store.get(Number(req.params.id));
  if (!order) return res.status(404).json({ error: "order not found" });
  res.json(order);
});

router.post("/", requireAuth, (req, res) => {
  const { item, qty } = req.body;
  if (!item || !Number.isInteger(qty) || qty < 1) {
    return res.status(400).json({ error: "item and positive integer qty required" });
  }
  res.status(201).json(store.insert({ item, qty }));
});

module.exports = router;

