// The in-memory order store. Every route reaches it through an INSTANCE
// (`const store = new OrderStore()`), which is the alias shape the graph must see.
class OrderStore {
  constructor() {
    this.items = new Map();
    this.nextId = 1;
  }

  list() {
    return [...this.items.values()];
  }

  get(id) {
    return this.items.get(id) || null;
  }

  insert(order) {
    const row = { id: this.nextId++, ...order };
    this.items.set(row.id, row);
    return row;
  }
}

// Search by the first letters of the item name. Reached by GET /orders/search
// and, through that route, by the supertest calls in tests/orders.test.js.
function searchByItemPrefix(orders, prefix) {
  const p = String(prefix || "").toLowerCase();
  return orders.filter((o) => String(o.item).toLowerCase().startsWith(p));
}

module.exports = { OrderStore, searchByItemPrefix };

tests/orders.test.js:
const request = require("supertest");
const app = require("../src/app");

describe("orders", () => {
  it("lists orders", async () => {
    const res = await request(app).get("/orders");
    expect(res.status).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
  });

  it("rejects unauthenticated create", async () => {
    const res = await request(app).post("/orders").send({ item: "mug", qty: 1 });
    expect(res.status).toBe(401);
  });

  it("creates an order when authenticated", async () => {
    const res = await request(app)
      .post("/orders")
      .set("authorization", "Bearer fixture-token")
      .send({ item: "mug", qty: 2 });
    expect(res.status).toBe(201);
    expect(res.body.id).toBeDefined();
  });

  it("searches by item prefix", async () => {
    await request(app).post("/orders").set("authorization", "Bearer fixture-token").send({ item: "mug", qty: 1 });
    const res = await request(app).get("/orders/search?q=mu");
    expect(res.status).toBe(200);
    expect(res.body.length).toBe(1);
  });

  it("search is case-insensitive", async () => {
    const res = await request(app).get("/orders/search?q=MU");
    expect(res.status).toBe(200);
  });

  it("search with no query returns everything", async () => {
    const res = await request(app).get("/orders/search");
    expect(res.status).toBe(200);
  });

  it("404s an unknown order", async () => {
    const res = await request(app).get("/orders/9999");
    expect(res.status).toBe(404);
  });
});

